import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';
import { useState, useEffect } from 'react';
import axios from 'axios';
import Button from '@mui/material/Button';

export default function AddCategory() {
  const [category, setCategory] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:7000/category/addCategory")
      .then((res) => {
        console.log(res.data.alluser);
        setCategory(res.data.alluser);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  return ( 
    <div>
      <h2>Category</h2>
      <TableContainer component={Paper}>
        <Table>

          <TableHead>
            <TableRow>
              <TableCell>Category details</TableCell>
              <TableCell align="right">SL.No</TableCell>
              <TableCell align="right">CategoryName</TableCell>
              <TableCell align="right">Description</TableCell>
            </TableRow>
          </TableHead>

          <TableBody>
            {category.map((row, index) => (
              <TableRow key={index}>
                {/* <TableCell align="right">{index + 1}</TableCell> */}
                <TableCell align="right">{row.name}</TableCell>
                <TableCell align="right">{row.Description}</TableCell>
                {/* <TableCell align="right">{row.phone}</TableCell> */}
                {/* <TableCell align="right">{row.address}</TableCell> */}
                {/* <Button variant='outlined'>UPDATE</Button> */}
                {/* <Button variant='outlined' onClick={()=>{HandleDelete(row._id)}}>DELETE</Button> */}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </div>
  );
}